  const { workbench } = useNavigationState();
  const { activeFileIndex } = useViewer();
  const { files: allFiles, fileIds } = useAllFiles();

  // Disable until all files are hydrated — running early would silently skip unloaded files.
  const isFilesHydrating = fileIds.length > allFiles.length;
  const effectiveDisabledReason =
    isFilesHydrating && props.disabledReason !== "endpointUnavailable"
      ? "filesLoading"
      : props.disabledReason;

  const isViewerMode = workbench === "viewer";
  const isFileEditorMode = workbench === "fileEditor";
  const hasMultipleFilesLoaded = allFiles.length > 1;
  const baseText = props.submitText ?? t("submit", "Submit");

  const disabledForViewerMode = props.disabledReason === "viewerMode";

  let scopedText = baseText;
  if (!disableScopeHints && !disabledForViewerMode) {
    if (isViewerMode && hasMultipleFilesLoaded) {
      scopedText = `${baseText} (${t("tool.scopeThisFile", "this file")})`;
    } else if (!isViewerMode && selectedFiles.length > 1) {
      scopedText = `${baseText} (${selectedFiles.length} ${t("tool.scopeFiles", "files")})`;
    }
  }

  const viewerFileName =
    !disableScopeHints &&
    !disabledForViewerMode &&
    isViewerMode &&
    hasMultipleFilesLoaded
      ? allFiles[activeFileIndex]?.name
      : null;

  const pendingCount = fileIds.length - allFiles.length;
  const isBulkLoading = pendingCount > 1;
  const loadProgress = isBulkLoading
    ? (allFiles.length / fileIds.length) * 100
    : 0;
  const showSelectFilesHint =
    !disableScopeHints &&
    isFileEditorMode &&
    allFiles.length > 0 &&
    selectedFiles.length === 0;

  const loadingVariant: ButtonVariant =
    operationButtonVariantMap[props.variant ?? "filled"] ?? "primary";
  const loadingAccent: ButtonAccent =
    operationButtonAccentMap[props.color ?? "blue"] ?? "default";

  return (
    <>
      {isFilesHydrating ? (
        <Box mx="md" mt="md">
          <Button
            fullWidth
            disabled
   * Pass the result of params.validateParameters().
   * createToolFlow uses this to show the 'invalidParams' disabled reason.
   */
  paramsValid?: boolean;
  /**
   * Explicit disabled reason override — use when the automatic computation
   * from endpointEnabled + paramsValid is insufficient.
   */
  disabledReason?: ExecuteDisabledReason;
  /** Raw override for tools with fully custom disable logic (e.g. Compare, ShowJS). */
  disabled?: boolean;
  testId?: string;
  showCloudBadge?: boolean;
  /** Suppress the automatic "(this file)" / "(N files)" scope hints in the button text. */
  disableScopeHints?: boolean;
}

export interface ReviewStepConfig<TParams = unknown> {
  isVisible: boolean;
  operation: ToolOperationHook<TParams>;
  title: string;
  onFileClick?: (file: File) => void;
  onUndo?: () => void;
  testId?: string;
}

